SELECT * FROM (SELECT CASE WHEN price >= 1200 THEN 'high' WHEN price >= 570 THEN 'mid' ELSE 'low' END AS price_bucket, supplier_id, MAX(price) AS max_price, MAX(launch_date) AS latest_launch_date FROM products WHERE stock_qty BETWEEN 363 AND 384 GROUP BY CASE WHEN price >= 1200 THEN 'high' WHEN price >= 570 THEN 'mid' ELSE 'low' END, supplier_id) AS s WHERE max_price < 650 ORDER BY price_bucket DESC, supplier_id LIMIT 1;
